func (q *Queries) ListStatusReplies(ctx context.Context, arg ListStatusRepliesParams) ([]Status, error) {
	rows, err := q.db.Query(ctx, listStatusReplies,
		arg.StatusID,
		arg.MinID,
		arg.AccountID,
		arg.ExcludeAccountID,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Status{}
	for rows.Next() {
		var i Status
		if err := rows.Scan(
			&i.ID,
			&i.Uri,
			&i.Text,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.InReplyToID,
			&i.ReblogOfID,
			&i.Url,
			&i.Sensitive,
			&i.Visibility,
			&i.SpoilerText,
			&i.Reply,
			&i.Language,
			&i.ConversationID,
			&i.Local,
			&i.AccountID,
			&i.ApplicationID,
			&i.InReplyToAccountID,
			&i.PollID,
			&i.DeletedAt,
			&i.EditedAt,
			&i.Trendable,
			&i.OrderedMediaAttachmentIds,
			&i.FetchedRepliesAt,
			&i.QuoteApprovalPolicy,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

